create table public.checkout_requests (id uuid primary key default gen_random_uuid(),reference text not null unique default ('CHK-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,10))),name text not null,email text not null,phone text not null,address text not null,cart jsonb not null,total_paise integer not null check(total_paise>=0),status text not null default 'new' check(status in('new','contacted','payment_link_sent','converted','cancelled')),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create index checkout_requests_queue_idx on public.checkout_requests(status,created_at desc);create trigger checkout_requests_updated_at before update on public.checkout_requests for each row execute procedure private.set_updated_at();alter table public.checkout_requests enable row level security;
create policy "public create checkout requests" on public.checkout_requests for insert to anon,authenticated with check(char_length(name) between 2 and 100 and char_length(address) between 8 and 1000 and total_paise>=0);
create policy "staff manage checkout requests" on public.checkout_requests for all to authenticated using((select private.is_staff())) with check((select private.is_staff()));grant insert on public.checkout_requests to anon,authenticated;grant select,update,delete on public.checkout_requests to authenticated;
